import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.taxProfiles().listTaxProfiles(Map.of("limit", 20));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("tax_profiles")) {
    Map<?, ?> taxProfile = (Map<?, ?>) row;
    System.out.println(taxProfile.get("id") + " " + taxProfile.get("name") + " " + taxProfile.get("default"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("total"));

